import React, { useState } from "react";
import { BrowserRouter, Navigate, Route, Routes } from "react-router-dom";
import { NavBarMenu } from "tabler-react";
import "tabler-react/style.css";

function Navegacion() {
  const [ultimo, setUltimo] = useState("Sin seleccionar");
  const items = [
    { value: "Resumen", to: "/app/resumen", icon: "grid", LinkComponent: true },
    { value: "Componentes", icon: "layers", subItems: [
      { value: "Datos", to: "/app/datos", LinkComponent: true, onClick: () => setUltimo("Datos") },
      { value: "Formulario", to: "/app/formulario", LinkComponent: true, onClick: () => setUltimo("Formulario") },
    ] },
    { value: "Gráficos", to: "/app/graficos", icon: "bar-chart-2", LinkComponent: true },
  ];
  return <>
    {/* Índice 1: compara resumen/graficos en los enlaces directos. */}
    <NavBarMenu items={items} rootIndex={1} />
    <p role="status">Último submenú: {ultimo}</p>
    <Routes>
      <Route path="/app/resumen" element={<p>Resumen de la aplicación</p>} />
      <Route path="/app/datos" element={<p>Tablas y datos</p>} />
      <Route path="/app/formulario" element={<p>Formulario</p>} />
      <Route path="/app/graficos" element={<p>Gráficos</p>} />
      <Route path="*" element={<Navigate to="/app/resumen" replace />} />
    </Routes>
  </>;
}

// Usa este Router solo en una aplicación que todavía no tenga uno.
export default function App() {
  return <BrowserRouter><Navegacion /></BrowserRouter>;
}
